const modal=document.createElement('dialog');modal.id='preview-dialog';document.body.append(modal);function show(title,message){modal.replaceChildren();const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=message;const b=document.createElement('button');b.textContent='Continuar navegando';b.onclick=()=>modal.close();modal.append(h,p,b);modal.showModal()}
