const slider=document.querySelector('#homeBannerPrincipal .swiper-container');const track=slider.querySelector('.swiper-wrapper');const slides=[...track.children].sort((a,b)=>(+a.dataset.swiperSlideIndex||0)-(+b.dataset.swiperSlideIndex||0));slides.forEach(s=>track.append(s));let current=0;function go(n){current=(n+slides.length)%slides.length;slider.scrollTo({left:current*slider.clientWidth,behavior:'smooth'})}const bullets=[...document.querySelectorAll('#homeBannerPrincipal .swiper-pagination-bullet')];bullets.forEach((b,i)=>{b.onclick=()=>go(i);b.setAttribute('aria-label','Banner '+(i+1))});slider.addEventListener('scroll',()=>{current=Math.round(slider.scrollLeft/slider.clientWidth);bullets.forEach((b,i)=>b.classList.toggle('swiper-pagination-bullet-active',i===current))});let rotating=setInterval(()=>{if(!document.hidden)go(current+1)},6000);slider.addEventListener('pointerdown',()=>clearInterval(rotating),{once:true});
const drawer=document.createElement('aside');drawer.className='exact-drawer';drawer.inert=true;drawer.innerHTML='<header><strong>Olá! Bem-vindo à Growth</strong><button aria-label="Fechar menu">×</button></header>';for(const group of [['Categorias','Kits','Proteínas','Veganos','Vegetarianos','Termogênicos','Vitaminas','Aminoácidos','Carboidratos','Acessórios'],['Objetivos','Massa muscular','Emagrecimento','Energia','Saúde e qualidade de vida']]){const d=document.createElement('details');const s=document.createElement('summary');s.textContent=group[0];d.append(s);for(const label of group.slice(1)){const a=document.createElement('a');a.href='/catalogo.html?categoria='+encodeURIComponent(({"top 20":"/top-20","lancamentos":"/c/lancamentos","whey":"/whey-protein","whey protein":"/whey-protein","creatina":"/creatina","kits":"/kits","ofertas":"/ofertas","pre-treino":"/pre-treino","vitaminas":"/vitaminas","roupas":"/roupas","snacks":"/snacks","proteinas":"/proteinas","veganos":"/veganos","vegetarianos":"/vegetarianos","termogenicos":"/termogenicos","aminoacidos":"/aminoacidos","carboidratos":"/carboidratos","acessorios":"/acessorios"})[label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()]||'/'+label.toLowerCase().replaceAll(' ','-'));a.textContent=label;d.append(a)}drawer.append(d)}for(const label of['Top 20','Lançamentos','Whey Protein','Creatina','Roupas','Snacks','Ofertas']){const a=document.createElement('a');a.href='/catalogo.html?categoria='+encodeURIComponent(({"top 20":"/top-20","lancamentos":"/c/lancamentos","whey":"/whey-protein","whey protein":"/whey-protein","creatina":"/creatina","kits":"/kits","ofertas":"/ofertas","pre-treino":"/pre-treino","vitaminas":"/vitaminas","roupas":"/roupas","snacks":"/snacks","proteinas":"/proteinas","veganos":"/veganos","vegetarianos":"/vegetarianos","termogenicos":"/termogenicos","aminoacidos":"/aminoacidos","carboidratos":"/carboidratos","acessorios":"/acessorios"})[label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()]||'/'+label.toLowerCase().replaceAll(' ','-'));a.textContent=label;drawer.append(a)}const overlay=document.createElement('div');overlay.className='exact-overlay';document.body.append(overlay,drawer);const menuButton=document.querySelector('.menu-toggle-btn');function close(){drawer.inert=true;drawer.classList.remove('open');overlay.classList.remove('open');document.body.style.overflow='';menuButton.setAttribute('aria-expanded','false');menuButton.focus()}menuButton.onclick=()=>{drawer.inert=false;drawer.classList.add('open');overlay.classList.add('open');document.body.style.overflow='hidden';menuButton.setAttribute('aria-expanded','true');drawer.querySelector('button').focus()};drawer.querySelector('button').onclick=close;overlay.onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('open'))close()});drawer.addEventListener('click',e=>{if(e.target.closest('a'))close()});
